/// Slot `slot` of `node`, a node of `kind` (checked in safety builds).
fn @"ir.at"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot] else .nil;
}

/// The children of `node` from `slot` on.
fn @"ir.restAt"(node: Sexp, comptime kind: Tag, comptime slot: usize, comptime what: []const u8) []const Sexp {
    @"ir.check"(node, kind, what);
    const items = node.items();
    return if (slot < items.len) items[slot..] else &.{};
}

fn @"ir.check"(node: Sexp, comptime kind: Tag, comptime what: []const u8) void {
    if (@import("builtin").optimize.runtimeSafety() and !node.isKind(kind)) {
        const actual = if (node.kind()) |k| @tagName(k) else @tagName(node);
        std.debug.panic(what ++ ": node is '{s}', not '" ++ @tagName(kind) ++ "'", .{actual});
    }
}


// =============================================================================
// Grammar
// =============================================================================

/// Node spans and rule ids are recorded (`@schema` or `--spans`).
pub const nodeStore = true;
/// Element extents are kept for side-band labels and nested nodes.
const elemEnds = true;
/// Lists keep trailing nils: positions are fixed by the schema.
const keepTrailingNils = true;
const hasTrivia = false;
/// The grammar has `@repair`: `parseTolerant` is available.
pub const hasRepair = false;
/// `@as` groups the promotable token may become (see `promote`).
const asGroups = 4;
const numSymbols = 300;
const endSymbol: u16 = 1;
const errorSymbol: u16 = 2;

inline fn tokenToSymbol(token: Token) u16 {
    return switch (token.cat) {
        .@"eof" => 1,
        .@"ident" => needsPromotion,
        .@"integer" => 138,
        .@"zdigits" => 139,
        .@"newline" => 140,
        .@"comment" => 141,
        .@"indent" => 147,
        .@"sp" => 150,
        .@"spaces" => 151,
        .@"string" => 206,
        .@"patend" => 212,
        .@"quesat" => 214,
        .@"real" => 282,
        .@"notques" => 235,
        .@"noteq" => 236,
        .@"notlt" => 239,
        .@"notgt" => 240,
        .@"notlbracket" => 243,
        .@"notrbracket" => 244,
        .@"followseq" => 245,
        .@"sortsafter" => 246,
        .@"sortsaftereq" => 247,
        .@"notsortsafter" => 248,
        .@"eqeq" => 273,
        .@"notampersand" => 275,
        .@"notexclaim" => 276,
        .@"lparen" => 142,
        .@"comma" => 143,
        .@"rparen" => 146,
        .@"dot" => 149,
        .@"colon" => 152,
        .@"at" => 155,
        .@"eq" => 156,
        .@"dollar" => 158,
        .@"plus" => 179,
        .@"caret" => 180,
        .@"pipe" => 189,
        .@"lbracket" => 190,
        .@"rbracket" => 191,
        .@"slash" => 203,
        .@"star" => 204,
        .@"hash" => 205,
        .@"exclaim" => 210,
        .@"question" => 211,
        .@"minus" => 221,
        .@"lt" => 237,
        .@"gt" => 238,
        .@"not" => 269,
        .@"underscore" => 270,
        .@"backslash" => 271,
        .@"ampersand" => 274,
        .@"lteq" => 241,
        .@"gteq" => 242,
        .@"starstar" => 272,
        else => 2, // error
    };
}

fn promote(self: *BaseParser, token: Token) u16 {
    // The ordinal of a match made in an earlier state (before a
    // reduction) is not this match's.
    self.lastMatchedId = 0;
    const text = self.tokenText(token);
    if (text.len == 0) return promotableSymbol;
    if (self.tryPromote(0, text, fnAs, &fnToSymbol, fnFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(1, text, isvAs, &isvToSymbol, isvFallbackSymbol, false)) |sym| return sym;
    if (self.tryPromote(2, text, ssvnAs, &ssvnToSymbol, ssvnFallbackSymbol, false)) |sym| return sym;
    if (getAction(self.stateStack.last().?, promotableSymbol) != 0) return promotableSymbol;
    if (self.tryPromote(3, text, cmdAs, &cmdToSymbol, cmdFallbackSymbol, true)) |sym| return sym;
    return promotableSymbol;
}

fn executeAction(self: *BaseParser, ruleId: u16, pass: []Sexp) Sexp {
    return switch (ruleId) {
        3 => blk: { const out = self.allocItems(1 + pass[0].items().len) catch break :blk self.oomNil(); var n: usize = 0; out[n] = .{ .tag = .@"routine" }; n += 1; @memcpy(out[n..][0..pass[0].items().len], pass[0].items()); n += pass[0].items().len; break :blk self.finishItems(out, .tree); },
        4 => self.buildOf(&.{ .nil }, pass, .spread, false),
