const promotableSymbol: u16 = 137;

/// The keyword terminals of `@keywords fn`; a value becomes its leaf's id.
pub const FnId = enum(u16) {
    ASCII = 200,
    CHAR,
    DATA,
    EXTRACT,
    FIND,
    FNUMBER,
    GET,
    INCREMENT,
    JUSTIFY,
    LENGTH,
    NAME,
    ORDER,
    PIECE,
    QLENGTH,
    QSUBSCRIPT,
    QUERY,
    RANDOM,
    REPLACE,
    REVERSE,
    SELECT,
    STACK,
    TEXT,
    TRANSLATE,
    VIEW,
    ZCONVERT,
    ZDATE,
    ZDATEH,
    ZDATETIME,
    ZLENGTH,
    ZMESSAGE,
    ZPREVIOUS,
    ZSEARCH,
    ZTIME,
    ZWRITE,
    NEXT,
    ZENV,
    ZF,
};

/// The `fn` keyword `text` spells, or null.
pub fn fnAs(text: []const u8) ?FnId {
    if (text.len == 0 or text.len > 10) return null;
    var folded: [10]u8 = undefined;
    const t = std.ascii.upperString(&folded, text);
    switch (t[0]) {
        'A' => {
            if (t.len <= 5 and std.mem.eql(u8, t, "ASCII"[0..t.len])) return .ASCII;
        },
        'C' => {
            if (t.len <= 4 and std.mem.eql(u8, t, "CHAR"[0..t.len])) return .CHAR;
        },
        'D' => {
            if (t.len <= 4 and std.mem.eql(u8, t, "DATA"[0..t.len])) return .DATA;
        },
        'E' => {
            if (t.len <= 7 and std.mem.eql(u8, t, "EXTRACT"[0..t.len])) return .EXTRACT;
        },
        'F' => {
            if (t.len <= 4 and std.mem.eql(u8, t, "FIND"[0..t.len])) return .FIND;
            if (t.len >= 2 and t.len <= 7 and std.mem.eql(u8, t, "FNUMBER"[0..t.len])) return .FNUMBER;
        },
        'G' => {
            if (t.len <= 3 and std.mem.eql(u8, t, "GET"[0..t.len])) return .GET;
        },
        'I' => {
            if (t.len <= 9 and std.mem.eql(u8, t, "INCREMENT"[0..t.len])) return .INCREMENT;
        },
        'J' => {
            if (t.len <= 7 and std.mem.eql(u8, t, "JUSTIFY"[0..t.len])) return .JUSTIFY;
        },
        'L' => {
            if (t.len <= 6 and std.mem.eql(u8, t, "LENGTH"[0..t.len])) return .LENGTH;
        },
        'N' => {
            if (t.len >= 2 and t.len <= 4 and std.mem.eql(u8, t, "NAME"[0..t.len])) return .NAME;
            if (t.len <= 4 and std.mem.eql(u8, t, "NEXT"[0..t.len])) return .NEXT;
        },
        'O' => {
            if (t.len <= 5 and std.mem.eql(u8, t, "ORDER"[0..t.len])) return .ORDER;
        },
        'P' => {
            if (t.len <= 5 and std.mem.eql(u8, t, "PIECE"[0..t.len])) return .PIECE;
        },
        'Q' => {
            if (t.len >= 2 and t.len <= 7 and std.mem.eql(u8, t, "QLENGTH"[0..t.len])) return .QLENGTH;
            if (t.len >= 2 and std.mem.eql(u8, t, "QSUBSCRIPT"[0..t.len])) return .QSUBSCRIPT;
            if (t.len <= 5 and std.mem.eql(u8, t, "QUERY"[0..t.len])) return .QUERY;
        },
        'R' => {
            if (t.len <= 6 and std.mem.eql(u8, t, "RANDOM"[0..t.len])) return .RANDOM;
            if (std.mem.eql(u8, t, "REPLACE")) return .REPLACE;
            if (t.len >= 2 and t.len <= 7 and std.mem.eql(u8, t, "REVERSE"[0..t.len])) return .REVERSE;
        },
        'S' => {
            if (t.len <= 6 and std.mem.eql(u8, t, "SELECT"[0..t.len])) return .SELECT;
            if (t.len >= 2 and t.len <= 5 and std.mem.eql(u8, t, "STACK"[0..t.len])) return .STACK;
        },
        'T' => {
            if (t.len <= 4 and std.mem.eql(u8, t, "TEXT"[0..t.len])) return .TEXT;
            if (t.len >= 2 and t.len <= 9 and std.mem.eql(u8, t, "TRANSLATE"[0..t.len])) return .TRANSLATE;
        },
        'V' => {
            if (t.len <= 4 and std.mem.eql(u8, t, "VIEW"[0..t.len])) return .VIEW;
        },
        'Z' => {
            if (t.len >= 3 and t.len <= 8 and std.mem.eql(u8, t, "ZCONVERT"[0..t.len])) return .ZCONVERT;
            if (t.len >= 2 and t.len <= 5 and std.mem.eql(u8, t, "ZDATE"[0..t.len])) return .ZDATE;
            if (std.mem.eql(u8, t, "ZDATEH")) return .ZDATEH;
            if (std.mem.eql(u8, t, "ZDATETIME")) return .ZDATETIME;
            if (std.mem.eql(u8, t, "ZENV")) return .ZENV;
            if (std.mem.eql(u8, t, "ZF")) return .ZF;
            if (std.mem.eql(u8, t, "ZINCR")) return .INCREMENT;
            if (std.mem.eql(u8, t, "ZINCREMENT")) return .INCREMENT;
            if (t.len >= 2 and t.len <= 7 and std.mem.eql(u8, t, "ZLENGTH"[0..t.len])) return .ZLENGTH;
            if (t.len >= 2 and t.len <= 8 and std.mem.eql(u8, t, "ZMESSAGE"[0..t.len])) return .ZMESSAGE;
            if (t.len >= 2 and t.len <= 9 and std.mem.eql(u8, t, "ZPREVIOUS"[0..t.len])) return .ZPREVIOUS;
            if (std.mem.eql(u8, t, "ZSEARCH")) return .ZSEARCH;
            if (std.mem.eql(u8, t, "ZT")) return .ZTIME;
            if (std.mem.eql(u8, t, "ZTIME")) return .ZTIME;
            if (std.mem.eql(u8, t, "ZTRNLNM")) return .ZENV;
            if (std.mem.eql(u8, t, "ZWRITE")) return .ZWRITE;
        },
        else => {},
    }
    return null;
}

