fn restRoleOf(kind: Tag) ?struct { role: Role, slot: usize } {
    return switch (kind) {
        .@"routine" => .{ .role = .@"lines", .slot = 1 },
        .@"label" => .{ .role = .@"cmds", .slot = 4 },
        .@"line" => .{ .role = .@"cmds", .slot = 2 },
        .@"commands" => .{ .role = .@"cmds", .slot = 1 },
        .@"set" => .{ .role = .@"args", .slot = 2 },
        .@"new" => .{ .role = .@"args", .slot = 2 },
        .@"kill" => .{ .role = .@"args", .slot = 2 },
        .@"merge" => .{ .role = .@"args", .slot = 2 },
        .@"do" => .{ .role = .@"args", .slot = 2 },
        .@"goto" => .{ .role = .@"args", .slot = 2 },
        .@"break" => .{ .role = .@"args", .slot = 2 },
        .@"hang" => .{ .role = .@"args", .slot = 2 },
        .@"job" => .{ .role = .@"args", .slot = 2 },
        .@"xecute" => .{ .role = .@"args", .slot = 2 },
        .@"view" => .{ .role = .@"args", .slot = 2 },
        .@"open" => .{ .role = .@"args", .slot = 2 },
        .@"use" => .{ .role = .@"args", .slot = 2 },
        .@"read" => .{ .role = .@"args", .slot = 2 },
        .@"write" => .{ .role = .@"args", .slot = 2 },
        .@"close" => .{ .role = .@"args", .slot = 2 },
        .@"lock" => .{ .role = .@"args", .slot = 2 },
        .@"zwrite" => .{ .role = .@"args", .slot = 2 },
        .@"zbreak" => .{ .role = .@"args", .slot = 2 },
        .@"zkill" => .{ .role = .@"args", .slot = 2 },
        .@"zlink" => .{ .role = .@"args", .slot = 2 },
        .@"zsystem" => .{ .role = .@"args", .slot = 2 },
        .@"zshow" => .{ .role = .@"args", .slot = 2 },
        .@"zsave" => .{ .role = .@"args", .slot = 2 },
        .@"zinsert" => .{ .role = .@"args", .slot = 2 },
        .@"zremove" => .{ .role = .@"args", .slot = 2 },
        .@"zprint" => .{ .role = .@"args", .slot = 2 },
        .@"if" => .{ .role = .@"conds", .slot = 1 },
        .@"for" => .{ .role = .@"params", .slot = 2 },
        .@"setmulti" => .{ .role = .@"targets", .slot = 2 },
        .@"setfn" => .{ .role = .@"args", .slot = 3 },
        .@"exclusive" => .{ .role = .@"names", .slot = 1 },
        .@"control" => .{ .role = .@"args", .slot = 2 },
        .@"posformat" => .{ .role = .@"marks", .slot = 2 },
        .@"lock=" => .{ .role = .@"refs", .slot = 2 },
        .@"lock+" => .{ .role = .@"refs", .slot = 2 },
        .@"lock-" => .{ .role = .@"refs", .slot = 2 },
        .@"vars" => .{ .role = .@"names", .slot = 1 },
        .@"zwarg" => .{ .role = .@"suffixes", .slot = 2 },
        .@"expr" => .{ .role = .@"tails", .slot = 2 },
        .@"naked" => .{ .role = .@"subs", .slot = 1 },
        .@"select" => .{ .role = .@"cases", .slot = 1 },
        .@"pat" => .{ .role = .@"alts", .slot = 5 },
        else => null,
    };
}

// =============================================================================
// API
// =============================================================================

pub const Parser = if (@hasDecl(lang, "Parser")) lang.Parser else BaseParser;

/// Parse a whole routine with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseRoutine(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseRoutine();
    return .{ .parser = p, .sexp = sexp };
}

/// Parse a whole commands with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseCommands(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
    errdefer p.deinit();
    const sexp = try p.parseCommands();
    return .{ .parser = p, .sexp = sexp };
}

/// Parse a whole expr with a new `Parser`. The caller owns
/// `result.parser` and must `deinit()` it when done with the tree.
pub fn parseExpr(allocator: std.mem.Allocator, source: []const u8) !struct { parser: Parser, sexp: Sexp } {
    var p = Parser.init(allocator, source);
